Criar página AdminLogin.tsx em /admin/login com formulário usando React Hook Form + Zod. Implementar validação de email (formato válido + domínios permitidos), senha obrigatória, checkbox 'Lembrar de mim', link 'Esqueci minha senha'. Usar shadcn/ui (Input, Checkbox, Button, Alert). Design com tema admin (cores mais escuras, profissional), logo Beauty Smile com subtítulo 'Administração', card centralizado com fundo gradient navy-teal.

Pseudo-código:
```typescript
const loginSchema = z.object({
  email: z.string().email('Email inválido').refine(
    (email) => ['beautysmile.com.br', 'beautysmile.com'].includes(email.split('@')[1]),
    'Domínio de email não autorizado'
  ),
  password: z.string().min(1, 'Senha é obrigatória'),
  rememberMe: z.boolean().default(false)
})

function AdminLogin() {
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema)
  })

  const onSubmit = async (data: LoginFormData) => {
    // lógica de autenticação
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-navy-900 to-teal-700 flex items-center justify-center">
      <Card className="w-full max-w-md p-8">
        <div className="text-center mb-8">
          <img src="/logo-admin.png" alt="Beauty Smile Administração" className="mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-gray-900">Painel Administrativo</h1>
        </div>
        <form onSubmit={handleSubmit(onSubmit)}>
          <Input type="email" placeholder="Email corporativo" {...register('email')} />
          <Input type="password" placeholder="Senha" {...register('password')} />
          <Checkbox {...register('rememberMe')}>Lembrar de mim</Checkbox>
          <Button type="submit" disabled={isSubmitting}>Entrar</Button>
        </form>
      </Card>
    </div>
  )
}
```

Implementar função de login que: 1) Autentica com supabase.auth.signInWithPassword(), 2) Verifica se usuário existe na tabela usuarios_rh e está ativo, 3) Valida domínio do email, 4) Busca role e permissões, 5) Atualiza store admin, 6) Redireciona para dashboard. Tratar todos os cenários de erro conforme especificado no PRD.

Pseudo-código:
```typescript
async function handleAdminLogin(formData: LoginFormData) {
  try {
    // 1. Autenticar com Supabase
    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email: formData.email,
      password: formData.password
    })

    if (authError) {
      handleAuthError(authError)
      await logFailedAttempt(formData.email, authError.message)
      return
    }

    // 2. Verificar se usuário está na tabela usuarios_rh
    const { data: adminUser, error: adminError } = await supabase
      .from('usuarios_rh')
      .select('*, permissoes_rh(*)')
      .eq('user_id', authData.user.id)
      .eq('ativo', true)
      .eq('deleted_at', null)
      .single()

    if (adminError || !adminUser) {
      showError('Você não tem permissão para acessar o painel administrativo.')
      await supabase.auth.signOut()
      await logUnauthorizedAttempt(authData.user.email)
      return
    }

    // 3. Verificar domínio do email
    const allowedDomains = ['beautysmile.com.br', 'beautysmile.com']
    const emailDomain = authData.user.email.split('@')[1]
    if (!allowedDomains.includes(emailDomain)) {
      showError('Domínio de email não autorizado.')
      await supabase.auth.signOut()
      return
    }

    // 4. Configurar sessão persistente
    if (formData.rememberMe) {
      await supabase.auth.setSession({
        access_token: authData.session.access_token,
        refresh_token: authData.session.refresh_token
      })
    }

    // 5. Atualizar store admin
    adminAuthStore.setState({
      user: authData.user,
      session: authData.session,
      adminUser: adminUser,
      role: adminUser.tipo_usuario,
      permissions: adminUser.permissoes_rh,
      isAuthenticated: true,
      isAdmin: adminUser.tipo_usuario === 'admin'
    })

    // 6. Log evento de sucesso
    await logLoginEvent({
      usuario_rh_id: adminUser.id,
      tipo_acesso: 'login',
      ip_address: await getClientIP(),
      user_agent: navigator.userAgent,
      sucesso: true
    })

    // 7. Redirecionar
    navigate('/admin/dashboard')
    toast.success('Login realizado com sucesso!')

  } catch (error) {
    console.error('Erro no login admin:', error)
    showError('Erro interno. Tente novamente.')
  }
}
```

Implementar funções para logging de eventos de acesso: logLoginEvent (sucesso), logFailedAttempt (falha), logUnauthorizedAttempt (sem permissão). Incluir parsing de user agent para extrair navegador, SO e dispositivo. Integrar detecção de IP do cliente usando API externa. Implementar alertas de segurança para múltiplas tentativas falhadas.

Pseudo-código:
```typescript
// Função para detectar IP do cliente
async function getClientIP(): Promise<string> {
  try {
    const response = await fetch('https://api.ipify.org?format=json')
    const data = await response.json()
    return data.ip
  } catch {
    return 'unknown'
  }
}

// Parser de user agent
function parseUserAgent(userAgent: string) {
  // Usar biblioteca ua-parser-js ou implementar parsing básico
  const parser = new UAParser(userAgent)
  return {
    navegador: `${parser.getBrowser().name} ${parser.getBrowser().version}`,
    sistema_operacional: `${parser.getOS().name} ${parser.getOS().version}`,
    dispositivo: parser.getDevice().type || 'desktop'
  }
}

// Log de login bem-sucedido
async function logLoginEvent(data: {
  usuario_rh_id: string
  tipo_acesso: string
  ip_address: string
  user_agent: string
  sucesso: boolean
}) {
  const deviceInfo = parseUserAgent(data.user_agent)

  const { error } = await supabase
    .from('logs_acesso')
    .insert([{
      usuario_rh_id: data.usuario_rh_id,
      tipo_acesso: data.tipo_acesso,
      ip_address: data.ip_address,
      user_agent: data.user_agent,
      navegador: deviceInfo.navegador,
      sistema_operacional: deviceInfo.sistema_operacional,
      dispositivo: deviceInfo.dispositivo,
      sucesso: data.sucesso
    }])

  if (error) console.error('Erro ao registrar log de acesso:', error)
}

// Log de tentativa falhada
async function logFailedAttempt(email: string, errorMessage: string) {
  const deviceInfo = parseUserAgent(navigator.userAgent)
  const ip = await getClientIP()

  const { error } = await supabase
    .from('logs_acesso')
    .insert([{
      email_tentativa: email,
      tipo_acesso: 'login_falho',
      ip_address: ip,
      user_agent: navigator.userAgent,
      navegador: deviceInfo.navegador,
      sistema_operacional: deviceInfo.sistema_operacional,
      dispositivo: deviceInfo.dispositivo,
      sucesso: false,
      motivo_falha: errorMessage
    }])

  // Verificar se precisa enviar alerta de segurança
  await checkSecurityAlerts(email, ip)
}

// Verificar alertas de segurança
async function checkSecurityAlerts(email: string, ip: string) {
  const thirtyMinutesAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString()

  // Verificar 5 tentativas falhadas para mesmo email em 30 min
  const { count: emailFailures } = await supabase
    .from('logs_acesso')
    .select('*', { count: 'exact' })
    .eq('email_tentativa', email)
    .eq('sucesso', false)
    .gte('created_at', thirtyMinutesAgo)

  if (emailFailures >= 5) {
    // Enviar alerta para equipe de segurança
    await sendSecurityAlert('multiple_failed_attempts', { email, count: emailFailures })
  }
}
```

Implementar mapeamento de códigos de erro do Supabase para mensagens user-friendly em português. Criar componente de alerta para exibir erros, implementar toast notifications para feedback. Tratar cenários específicos: credenciais inválidas, usuário não encontrado, email não confirmado, muitas tentativas, usuário banido, permissões insuficientes, erro de rede.

Pseudo-código:
```typescript
// Mapeamento de erros
const ERROR_MESSAGES = {
  'invalid_credentials': 'Email ou senha incorretos. Verifique seus dados e tente novamente.',
  'user_not_found': 'Credenciais inválidas ou conta não autorizada.',
  'email_not_confirmed': 'Seu email ainda não foi verificado. Verifique sua caixa de entrada.',
  'too_many_requests': 'Muitas tentativas de login. Sua conta foi temporariamente bloqueada. Tente novamente em 1 hora.',
  'user_banned': 'Sua conta foi desativada. Entre em contato com o administrador do sistema.',
  'insufficient_permissions': 'Você não tem permissão para acessar o painel administrativo. Contate o administrador.',
  'network_error': 'Erro de conexão. Verifique sua internet e tente novamente.',
  'default': 'Ocorreu um erro inesperado. Tente novamente ou contate o suporte.'
}

// Função para tratar erros de autenticação
function handleAuthError(error: AuthError) {
  let message = ERROR_MESSAGES.default
  let showContactSupport = false

  switch (error.message) {
    case 'Invalid login credentials':
      message = ERROR_MESSAGES.invalid_credentials
      break
    case 'User not found':
      message = ERROR_MESSAGES.user_not_found
      break
    case 'Email not confirmed':
      message = ERROR_MESSAGES.email_not_confirmed
      // Mostrar botão "Reenviar email"
      break
    case 'Too many requests':
      message = ERROR_MESSAGES.too_many_requests
      showContactSupport = true
      break
    default:
      if (error.message.includes('network') || error.message.includes('fetch')) {
        message = ERROR_MESSAGES.network_error
      }
  }

  // Exibir erro na UI
  setError(message)

  // Log do erro (sem dados sensíveis)
  console.error('Erro de autenticação:', {
    code: error.message,
    timestamp: new Date().toISOString()
  })
}

// Componente de erro
function ErrorAlert({ message, onRetry, showContactSupport }: {
  message: string
  onRetry?: () => void
  showContactSupport?: boolean
}) {
  return (
    <Alert variant="destructive" className="mb-4">
      <AlertCircle className="h-4 w-4" />
      <AlertTitle>Erro de Autenticação</AlertTitle>
      <AlertDescription className="mt-2">
        {message}
        {onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry} className="mt-2">
            Tentar Novamente
          </Button>
        )}
        {showContactSupport && (
          <div className="mt-2">
            <a href="mailto:ti@beautysmile.com.br" className="text-blue-600 underline">
              Contatar Suporte TI
            </a>
          </div>
        )}
      </AlertDescription>
    </Alert>
  )
}
```

Implementar lógica de sessão: 'Lembrar de mim' marcado = 7 dias no localStorage, desmarcado = 8 horas no sessionStorage. Configurar timeout de inatividade (30 minutos), modal de aviso antes do logout automático, sincronização entre abas usando BroadcastChannel API.

Pseudo-código:
```typescript
// Configuração de sessão baseada em 'Lembrar de mim'
async function configureSession(rememberMe: boolean, session: Session) {
  const storage = rememberMe ? 'local' : 'session'
  const duration = rememberMe ? 7 * 24 * 60 * 60 : 8 * 60 * 60 // 7 dias ou 8 horas em segundos

  // Configurar persistência no Supabase
  await supabase.auth.setSession({
    access_token: session.access_token,
    refresh_token: session.refresh_token
  })

  // Armazenar preferência de sessão
  const sessionConfig = {
    rememberMe,
    expiresAt: Date.now() + (duration * 1000),
    lastActivity: Date.now()
  }

  if (rememberMe) {
    localStorage.setItem('admin_session_config', JSON.stringify(sessionConfig))
  } else {
    sessionStorage.setItem('admin_session_config', JSON.stringify(sessionConfig))
  }
}

// Monitor de inatividade
class InactivityMonitor {
  private timeoutId: NodeJS.Timeout | null = null
  private warningTimeoutId: NodeJS.Timeout | null = null
  private readonly INACTIVITY_LIMIT = 30 * 60 * 1000 // 30 minutos
  private readonly WARNING_TIME = 5 * 60 * 1000 // 5 minutos antes

  start() {
    this.resetTimer()

    // Eventos que resetam o timer
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'click']
    events.forEach(event => {
      document.addEventListener(event, () => this.resetTimer(), true)
    })
  }

  resetTimer() {
    if (this.timeoutId) clearTimeout(this.timeoutId)
    if (this.warningTimeoutId) clearTimeout(this.warningTimeoutId)

    // Aviso 5 minutos antes do logout
    this.warningTimeoutId = setTimeout(() => {
      this.showInactivityWarning()
    }, this.INACTIVITY_LIMIT - this.WARNING_TIME)

    // Logout automático
    this.timeoutId = setTimeout(() => {
      this.handleInactivityLogout()
    }, this.INACTIVITY_LIMIT)

    // Atualizar última atividade
    this.updateLastActivity()
  }

  showInactivityWarning() {
    // Modal: "Sua sessão expirará em 5 minutos por inatividade"
    const confirmed = window.confirm(
      'Sua sessão expirará em 5 minutos por inatividade. Deseja continuar conectado?'
    )

    if (confirmed) {
      this.resetTimer() // Estender sessão
    }
  }

  async handleInactivityLogout() {
    await adminAuthStore.getState().logout()
    toast.info('Sessão encerrada por inatividade')
    navigate('/admin/login')
  }

  updateLastActivity() {
    const config = this.getSessionConfig()
    if (config) {
      config.lastActivity = Date.now()
      this.saveSessionConfig(config)
    }
  }
}

// Sincronização entre abas
class TabSyncManager {
  private channel: BroadcastChannel

  constructor() {
    this.channel = new BroadcastChannel('admin_auth_sync')
    this.channel.addEventListener('message', this.handleMessage.bind(this))
  }

  broadcastLogout() {
    this.channel.postMessage({ type: 'LOGOUT' })
  }

  broadcastSessionUpdate(session: Session) {
    this.channel.postMessage({ type: 'SESSION_UPDATE', session })
  }

  handleMessage(event: MessageEvent) {
    switch (event.data.type) {
      case 'LOGOUT':
        // Fazer logout em todas as abas
        adminAuthStore.getState().clearAdminUser()
        navigate('/admin/login')
        break
      case 'SESSION_UPDATE':
        // Atualizar sessão em todas as abas
        adminAuthStore.getState().setSession(event.data.session)
        break
    }
  }
}
```

Criar ProtectedAdminRoute que verifica autenticação e role do usuário. Implementar hierarquia de permissões (admin > rh_avancado > rh_basico). Configurar redirecionamentos apropriados para usuários não autenticados ou sem permissão. Criar hook usePermission para verificações granulares.

Pseudo-código:
```typescript
// Componente de rota protegida
interface ProtectedAdminRouteProps {
  children: React.ReactNode
  requiredRole?: 'rh_basico' | 'rh_avancado' | 'admin'
  requiredPermission?: string
}

export function ProtectedAdminRoute({
  children,
  requiredRole,
  requiredPermission
}: ProtectedAdminRouteProps) {
  const { isAuthenticated, role, isLoading, hasPermission } = useAdminAuthStore()
  const location = useLocation()

  // Mostrar loading enquanto verifica autenticação
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <Spinner className="mx-auto mb-4" />
          <p>Verificando permissões...</p>
        </div>
      </div>
    )
  }

  // Redirecionar para login se não autenticado
  if (!isAuthenticated) {
    return <Navigate to="/admin/login" state={{ from: location }} replace />
  }

  // Verificar role necessário
  if (requiredRole && !hasRequiredRole(role, requiredRole)) {
    return <Navigate to="/admin/unauthorized" replace />
  }

  // Verificar permissão específica
  if (requiredPermission && !hasPermission(requiredPermission)) {
    return <Navigate to="/admin/unauthorized" replace />
  }

  return <>{children}</>
}

// Função para verificar hierarquia de roles
function hasRequiredRole(
  userRole: string | null,
  requiredRole: string
): boolean {
  if (!userRole) return false

  const roleHierarchy = {
    'admin': 3,
    'rh_avancado': 2,
    'rh_basico': 1
  }

  return roleHierarchy[userRole] >= roleHierarchy[requiredRole]
}

// Hook para verificação de permissões
export function usePermission(permission: string): boolean {
  const { role, permissions } = useAdminAuthStore()

  // Admin tem todas as permissões
  if (role === 'admin') return true

  // Verificar permissão específica
  return permissions?.[permission] === true
}

// Configuração de rotas
function AdminRoutes() {
  return (
    <Routes>
      <Route path="/admin/login" element={<AdminLogin />} />
      <Route path="/admin/unauthorized" element={<UnauthorizedPage />} />

      {/* Rotas que requerem autenticação básica */}
      <Route path="/admin/dashboard" element={
        <ProtectedAdminRoute>
          <AdminDashboard />
        </ProtectedAdminRoute>
      } />

      <Route path="/admin/candidatos" element={
        <ProtectedAdminRoute>
          <CandidatesList />
        </ProtectedAdminRoute>
      } />

      {/* Rotas que requerem RH avançado ou admin */}
      <Route path="/admin/candidatos/:id/edit" element={
        <ProtectedAdminRoute requiredRole="rh_avancado">
          <EditCandidate />
        </ProtectedAdminRoute>
      } />

      <Route path="/admin/analytics" element={
        <ProtectedAdminRoute requiredRole="rh_avancado">
          <Analytics />
        </ProtectedAdminRoute>
      } />

      {/* Rotas que requerem admin */}
      <Route path="/admin/usuarios" element={
        <ProtectedAdminRoute requiredRole="admin">
          <UserManagement />
        </ProtectedAdminRoute>
      } />

      <Route path="/admin/settings" element={
        <ProtectedAdminRoute requiredRole="admin">
          <SystemSettings />
        </ProtectedAdminRoute>
      } />
    </Routes>
  )
}

// Página de não autorizado
function UnauthorizedPage() {
  const navigate = useNavigate()

  return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="text-center">
        <h1 className="text-2xl font-bold text-red-600 mb-4">
          Acesso Negado
        </h1>
        <p className="text-gray-600 mb-6">
          Você não tem permissão para acessar esta página.
        </p>
        <Button onClick={() => navigate('/admin/dashboard')}>
          Voltar ao Dashboard
        </Button>
      </div>
    </div>
  )
}
```

Implementar função de logout que: 1) Mostra modal de confirmação, 2) Registra evento de logout, 3) Chama supabase.auth.signOut(), 4) Limpa store admin, 5) Limpa storage local/session, 6) Sincroniza logout entre abas, 7) Redireciona para login. Adicionar botão de logout no header admin.

Pseudo-código:
```typescript
// Função de logout no store
const useAdminAuthStore = create<AdminAuthState>((set, get) => ({
  // ... outros estados

  logout: async () => {
    const { adminUser } = get()

    try {
      // 1. Registrar evento de logout
      if (adminUser) {
        await logLoginEvent({
          usuario_rh_id: adminUser.id,
          tipo_acesso: 'logout',
          ip_address: await getClientIP(),
          user_agent: navigator.userAgent,
          sucesso: true
        })
      }

      // 2. Fazer logout no Supabase
      await supabase.auth.signOut()

      // 3. Limpar storage
      localStorage.removeItem('admin_session_config')
      sessionStorage.removeItem('admin_session_config')

      // 4. Limpar estado
      set({
        user: null,
        session: null,
        adminUser: null,
        role: null,
        permissions: null,
        isAuthenticated: false,
        isAdmin: false
      })

      // 5. Sincronizar logout entre abas
      tabSyncManager.broadcastLogout()

      // 6. Parar monitor de inatividade
      inactivityMonitor.stop()

    } catch (error) {
      console.error('Erro durante logout:', error)
      // Mesmo com erro, limpar estado local
      set({
        user: null,
        session: null,
        adminUser: null,
        role: null,
        permissions: null,
        isAuthenticated: false,
        isAdmin: false
      })
    }
  }
}))

// Componente de botão de logout
function LogoutButton() {
  const { logout } = useAdminAuthStore()
  const navigate = useNavigate()
  const [showConfirm, setShowConfirm] = useState(false)
  const [isLoggingOut, setIsLoggingOut] = useState(false)

  const handleLogout = async () => {
    setIsLoggingOut(true)

    try {
      await logout()
      toast.success('Logout realizado com sucesso')
      navigate('/admin/login')
    } catch (error) {
      toast.error('Erro ao fazer logout')
    } finally {
      setIsLoggingOut(false)
      setShowConfirm(false)
    }
  }

  return (
    <>
      <Button
        variant="ghost"
        onClick={() => setShowConfirm(true)}
        className="text-red-600 hover:text-red-700"
      >
        <LogOut className="w-4 h-4 mr-2" />
        Sair
      </Button>

      <AlertDialog open={showConfirm} onOpenChange={setShowConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar Logout</AlertDialogTitle>
            <AlertDialogDescription>
              Deseja realmente sair do painel administrativo?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleLogout}
              disabled={isLoggingOut}
              className="bg-red-600 hover:bg-red-700"
            >
              {isLoggingOut ? (
                <>
                  <Spinner className="w-4 h-4 mr-2" />
                  Saindo...
                </>
              ) : (
                'Confirmar Saída'
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

// Header admin com logout
function AdminHeader() {
  const { adminUser, role } = useAdminAuthStore()

  return (
    <header className="bg-white shadow-sm border-b px-6 py-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <img src="/logo-admin.png" alt="Beauty Smile" className="h-8" />
          <div>
            <h1 className="text-lg font-semibold">Painel Administrativo</h1>
            <p className="text-sm text-gray-500">
              {adminUser?.nome} • {getRoleLabel(role)}
            </p>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <span className="text-sm text-gray-600">
            Último acesso: {formatLastAccess(adminUser?.ultimo_acesso)}
          </span>
          <LogoutButton />
        </div>
      </div>
    </header>
  )
}
