Implementar função de inicialização que verifica se existe sessão válida no Supabase, valida se usuário ainda está ativo na tabela usuarios_rh, verifica expiração baseada em configuração de sessão, e restaura estado admin. Integrar com listener de mudanças de auth state.

Pseudo-código:
```typescript
// Função de inicialização da sessão admin
async function initializeAdminAuth() {
  try {
    adminAuthStore.setState({ isLoading: true })

    // 1. Verificar sessão existente no Supabase
    const { data: { session }, error } = await supabase.auth.getSession()

    if (error || !session) {
      adminAuthStore.setState({ isLoading: false })
      return
    }

    // 2. Verificar se sessão não expirou baseado na configuração local
    const sessionConfig = getSessionConfig()
    if (sessionConfig && Date.now() > sessionConfig.expiresAt) {
      await supabase.auth.signOut()
      clearSessionConfig()
      adminAuthStore.setState({ isLoading: false })
      return
    }

    // 3. Verificar se usuário ainda está ativo na tabela usuarios_rh
    const { data: adminUser, error: adminError } = await supabase
      .from('usuarios_rh')
      .select('*, permissoes_rh(*)')
      .eq('user_id', session.user.id)
      .eq('ativo', true)
      .eq('deleted_at', null)
      .single()

    if (adminError || !adminUser) {
      // Usuário foi desativado ou removido
      await supabase.auth.signOut()
      clearSessionConfig()
      adminAuthStore.setState({ isLoading: false })
      toast.error('Sua conta foi desativada. Contate o administrador.')
      return
    }

    // 4. Verificar domínio do email ainda é válido
    const allowedDomains = ['beautysmile.com.br', 'beautysmile.com']
    const emailDomain = session.user.email?.split('@')[1]
    if (!emailDomain || !allowedDomains.includes(emailDomain)) {
      await supabase.auth.signOut()
      clearSessionConfig()
      adminAuthStore.setState({ isLoading: false })
      return
    }

    // 5. Restaurar estado admin
    adminAuthStore.setState({
      user: session.user,
      session: session,
      adminUser: adminUser,
      role: adminUser.tipo_usuario,
      permissions: adminUser.permissoes_rh,
      isAuthenticated: true,
      isAdmin: adminUser.tipo_usuario === 'admin',
      isLoading: false
    })

    // 6. Iniciar monitor de inatividade
    inactivityMonitor.start()

    // 7. Log de sessão restaurada
    await logLoginEvent({
      usuario_rh_id: adminUser.id,
      tipo_acesso: 'sessao_restaurada',
      ip_address: await getClientIP(),
      user_agent: navigator.userAgent,
      sucesso: true
    })

  } catch (error) {
    console.error('Erro ao inicializar auth admin:', error)
    adminAuthStore.setState({ isLoading: false })
  }
}

// Listener para mudanças de estado de auth
supabase.auth.onAuthStateChange(async (event, session) => {
  console.log('Admin auth state change:', event)

  switch (event) {
    case 'SIGNED_IN':
      // Sessão criada - já tratado no login
      break

    case 'SIGNED_OUT':
      // Sessão encerrada
      adminAuthStore.setState({
        user: null,
        session: null,
        adminUser: null,
        role: null,
        permissions: null,
        isAuthenticated: false,
        isAdmin: false
      })
      clearSessionConfig()
      inactivityMonitor.stop()
      break

    case 'TOKEN_REFRESHED':
      // Token renovado - atualizar sessão
      if (session) {
        adminAuthStore.setState({ session })
        updateSessionConfig({ lastActivity: Date.now() })
      }
      break

    case 'USER_UPDATED':
      // Dados do usuário atualizados
      if (session) {
        adminAuthStore.setState({ user: session.user })
      }
      break
  }
})

// Funções auxiliares para gerenciar configuração de sessão
function getSessionConfig(): SessionConfig | null {
  try {
    const config = localStorage.getItem('admin_session_config') || 
                  sessionStorage.getItem('admin_session_config')
    return config ? JSON.parse(config) : null
  } catch {
    return null
  }
}

function clearSessionConfig() {
  localStorage.removeItem('admin_session_config')
  sessionStorage.removeItem('admin_session_config')
}

function updateSessionConfig(updates: Partial<SessionConfig>) {
  const current = getSessionConfig()
  if (current) {
    const updated = { ...current, ...updates }
    const storage = current.rememberMe ? localStorage : sessionStorage
    storage.setItem('admin_session_config', JSON.stringify(updated))
  }
}

// Hook para inicialização
export function useAdminAuthInitialization() {
  useEffect(() => {
    initializeAdminAuth()
  }, [])
}

// Componente raiz da aplicação admin
function AdminApp() {
  useAdminAuthInitialization()
  const { isLoading } = useAdminAuthStore()

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <Spinner className="mx-auto mb-4" size="lg" />
          <h2 className="text-lg font-semibold mb-2">Beauty Smile Admin</h2>
          <p className="text-gray-600">Carregando painel administrativo...</p>
        </div>
      </div>
    )
  }

  return <AdminRoutes />
}
