const calculateStatistics = (candidato: Candidato) => {
  // Tempo no processo
  const daysInProcess = Math.floor(
    (Date.now() - new Date(candidato.data_cadastro).getTime()) / (1000 * 60 * 60 * 24)
  )

  // Testes concluídos
  const completedTests = [
    candidato.big_five_completo,
    candidato.disc_completo,
    candidato.raven_completo
  ].filter(Boolean).length

  const totalTests = 3

  // Taxa de conclusão
  const completionRate = Math.round((completedTests / totalTests) * 100)

  // Próxima etapa
  const nextStage = getNextStage(candidato.etapa_atual)

  return {
    daysInProcess,
    completedTests,
    totalTests,
    completionRate,
    nextStage
  }
}
