2. Implementar cálculo de completude:
```typescript
const calculateProfileCompleteness = (candidato: Candidato) => {
  const requiredFields = [
    'nome_completo',
    'email',
    'telefone',
    'data_nascimento',
    'endereco_completo',
    'cidade',
    'estado',
    'cep',
    'escolaridade',
    'experiencia_profissional',
    'foto_perfil'
  ]

  const completedFields = requiredFields.filter(field => {
    const value = candidato[field]
    return value && value.toString().trim() !== ''
  })

  return Math.round((completedFields.length / requiredFields.length) * 100)
}

const getMissingProfileFields = (candidato: Candidato) => {
  const fieldLabels = {
    telefone: 'Telefone',
    data_nascimento: 'Data de nascimento',
    endereco_completo: 'Endereço',
    cidade: 'Cidade',
    estado: 'Estado',
    cep: 'CEP',
    escolaridade: 'Escolaridade',
    experiencia_profissional: 'Experiência profissional',
    foto_perfil: 'Foto de perfil'
  }

  const missingFields = []

  Object.entries(fieldLabels).forEach(([field, label]) => {
    const value = candidato[field]
    if (!value || value.toString().trim() === '') {
      missingFields.push(label)
    }
  })

  return missingFields
}
```

