1. Configurar Supabase real-time subscriptions:
```typescript
const useRealtimeUpdates = (candidatoId: string) => {
  const queryClient = useQueryClient()

  useEffect(() => {
    // Subscription para mudanças no candidato
    const candidatoSubscription = supabase
      .channel('candidato_changes')
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'candidatos',
        filter: `id=eq.${candidatoId}`
      }, (payload) => {
        // Atualizar cache do candidato
        queryClient.setQueryData(['candidato', candidatoId], payload.new)

        // Mostrar notificação se etapa mudou
        if (payload.old.etapa_atual !== payload.new.etapa_atual) {
          toast.success(`Parabéns! Você avançou para: ${formatStageName(payload.new.etapa_atual)}`)
        }
      })
      .subscribe()

    // Subscription para novas notificações
    const notificationsSubscription = supabase
      .channel('new_notifications')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'notificacoes',
        filter: `candidato_id=eq.${candidatoId}`
      }, (payload) => {
        // Invalidar cache de notificações
        queryClient.invalidateQueries(['notifications', candidatoId])
        queryClient.invalidateQueries(['unread-notifications', candidatoId])

        // Mostrar toast de nova notificação
        toast.info('Nova notificação recebida!', {
          action: {
            label: 'Ver',
            onClick: () => scrollToNotifications()
          }
        })
      })
      .subscribe()

    // Subscription para mudanças em candidaturas
    const candidaturasSubscription = supabase
      .channel('candidaturas_changes')
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'candidaturas',
        filter: `candidato_id=eq.${candidatoId}`
      }, (payload) => {
        queryClient.invalidateQueries(['candidaturas', candidatoId])

        if (payload.eventType === 'UPDATE' && payload.old.status !== payload.new.status) {
          toast.info(`Status da candidatura atualizado: ${payload.new.status}`)
        }
      })
      .subscribe()

    return () => {
      candidatoSubscription.unsubscribe()
      notificationsSubscription.unsubscribe()
      candidaturasSubscription.unsubscribe()
    }
  }, [candidatoId, queryClient])
}
