const useRealtimeFallback = (candidatoId: string) => {
  const [realtimeConnected, setRealtimeConnected] = useState(true)
  const queryClient = useQueryClient()

  useEffect(() => {
    let pollInterval: NodeJS.Timeout

    // Se real-time falhar, usar polling
    if (!realtimeConnected) {
      pollInterval = setInterval(() => {
        queryClient.invalidateQueries(['candidato', candidatoId])
        queryClient.invalidateQueries(['notifications', candidatoId])
      }, 30000) // Poll a cada 30 segundos
    }

    return () => {
      if (pollInterval) clearInterval(pollInterval)
    }
  }, [realtimeConnected, candidatoId, queryClient])

  // Monitorar status da conexão real-time
  useEffect(() => {
    const channel = supabase.channel('connection_test')

    channel.on('presence', { event: 'sync' }, () => {
      setRealtimeConnected(true)
    })

    channel.subscribe((status) => {
      if (status === 'CHANNEL_ERROR') {
        setRealtimeConnected(false)
      }
    })

    return () => channel.unsubscribe()
  }, [])
}
