```typescript
const useDataState = <T>(queryResult: UseQueryResult<T>) => {
  const { data, isLoading, error, refetch, isError } = queryResult

  const isEmpty = useMemo(() => {
    if (!data) return false
    if (Array.isArray(data)) return data.length === 0
    if (typeof data === 'object') return Object.keys(data).length === 0
    return false
  }, [data])

  return {
    data,
    isLoading,
    isError,
    isEmpty,
    error,
    refetch,
    // Helpers para renderização condicional
    showLoading: isLoading,
    showError: isError && !isLoading,
    showEmpty: !isLoading && !isError && isEmpty,
    showData: !isLoading && !isError && !isEmpty
  }
}
```

