const DataStateWrapper = ({ 
  children, 
  queryResult, 
  LoadingComponent = SectionSkeleton,
  ErrorComponent = ErrorState,
  EmptyComponent,
  emptyMessage = "Nenhum dado encontrado"
}) => {
  const { showLoading, showError, showEmpty, showData, error, refetch } = useDataState(queryResult)

  if (showLoading) {
