    // Prefetch dados que provavelmente serão necessários
    const prefetchTimer = setTimeout(() => {
      // Prefetch candidaturas se ainda não carregadas
      queryClient.prefetchQuery({
        queryKey: ['candidaturas', candidatoId],
        queryFn: () => fetchCandidaturas(candidatoId),
        staleTime: 5 * 60 * 1000
      })

      // Prefetch notificações
      queryClient.prefetchQuery({
        queryKey: ['notifications', candidatoId],
        queryFn: () => fetchNotifications(candidatoId),
        staleTime: 2 * 60 * 1000
      })
    }, 1000) // Aguardar 1s após carregamento inicial

    return () => clearTimeout(prefetchTimer)
  }, [candidatoId, queryClient])
}
