- Não possui resultado DISC completo

```typescript
// hooks/useDISCAccess.ts
export function useDISCAccess() {
  const { user } = useAuth()
  const [canAccess, setCanAccess] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    async function checkAccess() {
      if (!user) {
        setError('Usuário não autenticado')
        return
      }

      const { data: candidato } = await supabase
        .from('candidatos')
        .select('etapa_atual')
        .eq('user_id', user.id)
        .single()

      if (candidato?.etapa_atual !== 'disc') {
        setError('Teste DISC não disponível nesta etapa')
        return
      }

      const { data: resultado } = await supabase
        .from('resultados_disc')
        .select('id')
        .eq('candidato_id', candidato.id)
        .single()

      if (resultado) {
        setError('Teste DISC já foi concluído')
        return
      }

      setCanAccess(true)
    }

    checkAccess().finally(() => setLoading(false))
  }, [user])

  return { canAccess, loading, error }
}
