```typescript
// hooks/useDISCQuestions.ts
export function useDISCQuestions() {
  const [questions, setQuestions] = useState<DISCQuestion[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    async function loadQuestions() {
      try {
        const { data, error } = await supabase
          .from('biblioteca_perguntas')
          .select('*')
          .eq('tipo_teste', 'disc')
          .order('numero_questao', { ascending: true })

        if (error) throw error

        if (!data || data.length !== 28) {
          throw new Error(`Esperado 28 perguntas, encontrado ${data?.length || 0}`)
        }

        // Validar estrutura das perguntas
        const validQuestions = data.every(q => 
          q.opcoes_resposta &&
          ['A', 'B', 'C', 'D'].every(key => 
            q.opcoes_resposta[key]?.texto &&
            ['D', 'I', 'S', 'C'].includes(q.opcoes_resposta[key]?.dimensao)
          )
        )

        if (!validQuestions) {
          throw new Error('Estrutura de perguntas inválida')
        }

        setQuestions(data)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Erro ao carregar perguntas')
      } finally {
        setLoading(false)
      }
    }

    loadQuestions()
  }, [])

  return { questions, loading, error }
}
