interface DISCQuestionProps {
  question: DISCQuestion
  questionNumber: number
  totalQuestions: number
  answer: DISCAnswer | null
  onAnswerChange: (most: string, least: string) => void
  onNext: () => void
  onPrevious: () => void
  canGoNext: boolean
}

export function DISCQuestion({
  question,
  questionNumber,
  totalQuestions,
  answer,
  onAnswerChange,
  onNext,
  onPrevious,
  canGoNext
}: DISCQuestionProps) {
  const [mostSelected, setMostSelected] = useState<string | null>(answer?.most || null)
  const [leastSelected, setLeastSelected] = useState<string | null>(answer?.least || null)
  const progress = Math.round((questionNumber / totalQuestions) * 100)

  const handleMostClick = (option: string) => {
    if (option === leastSelected) return // Não pode ser ambos

    const newMost = mostSelected === option ? null : option
    setMostSelected(newMost)

    if (newMost && leastSelected) {
      onAnswerChange(newMost, leastSelected)
    }
  }

  const handleLeastClick = (option: string) => {
    if (option === mostSelected) return // Não pode ser ambos

    const newLeast = leastSelected === option ? null : option
    setLeastSelected(newLeast)

    if (mostSelected && newLeast) {
      onAnswerChange(mostSelected, newLeast)
    }
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* Header com progresso */}
      <div className="mb-8">
        <div className="flex justify-between items-center mb-2">
          <span className="text-sm text-gray-600">Pergunta {questionNumber} de {totalQuestions}</span>
          <span className="text-sm text-gray-600">{progress}% completo</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div className="bg-blue-600 h-2 rounded-full transition-all" style={{ width: `${progress}%` }}></div>
        </div>
      </div>

      {/* Número da pergunta */}
      <div className="text-center mb-6">
        <div className="text-6xl font-bold text-gray-800 mb-2">{questionNumber}</div>
        <p className="text-lg text-gray-600">Selecione a característica que <strong>MAIS</strong> e <strong>MENOS</strong> descrevem você:</p>
      </div>

      {/* Opções */}
      <div className="grid gap-4 mb-8">
        {Object.entries(question.opcoes_resposta).map(([key, option]) => (
          <div key={key} className="bg-white border-2 border-gray-200 rounded-lg p-4 hover:border-gray-300 transition-colors">
            <div className="flex items-center justify-between">
              <span className="text-lg font-medium">{option.texto}</span>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleMostClick(key)}
                  disabled={key === leastSelected}
                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                    mostSelected === key
                      ? 'bg-green-600 text-white'
                      : key === leastSelected
                      ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                      : 'bg-green-100 text-green-700 hover:bg-green-200'
                  }`}
                >
                  ✅ MAIS
                </button>
                <button
                  onClick={() => handleLeastClick(key)}
                  disabled={key === mostSelected}
                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                    leastSelected === key
                      ? 'bg-red-600 text-white'
                      : key === mostSelected
                      ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                      : 'bg-red-100 text-red-700 hover:bg-red-200'
                  }`}
                >
                  ❌ MENOS
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Navegação */}
      <div className="flex justify-between">
        <button
          onClick={onPrevious}
          disabled={questionNumber === 1}
          className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <div className="relative">
          <button
            onClick={onNext}
            disabled={!canGoNext}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {questionNumber === totalQuestions ? 'Finalizar' : 'Próxima'}
          </button>
          {!canGoNext && (
            <div className="absolute -top-10 left-1/2 transform -translate-x-1/2 bg-gray-800 text-white text-xs px-2 py-1 rounded whitespace-nowrap">
              Selecione uma opção MAIS e uma MENOS
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
```

