```typescript
export function useDISCTest(questions: DISCQuestion[]) {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)
  const [answers, setAnswers] = useState<(DISCAnswer | null)[]>(
    new Array(questions.length).fill(null)
  )
  const [startTime] = useState(Date.now())

  // Salvar no localStorage para recuperação
  useEffect(() => {
    const testState = {
      currentQuestionIndex,
      answers,
      startTime
    }
    localStorage.setItem('disc-test-state', JSON.stringify(testState))
  }, [currentQuestionIndex, answers, startTime])

  // Recuperar estado do localStorage
  useEffect(() => {
    const saved = localStorage.getItem('disc-test-state')
    if (saved) {
      try {
        const state = JSON.parse(saved)
        setCurrentQuestionIndex(state.currentQuestionIndex || 0)
        setAnswers(state.answers || new Array(questions.length).fill(null))
      } catch (error) {
        console.warn('Erro ao recuperar estado do teste:', error)
      }
    }
  }, [])

  const setAnswer = useCallback((questionIndex: number, most: string, least: string) => {
    setAnswers(prev => {
      const newAnswers = [...prev]
      newAnswers[questionIndex] = { most, least }
      return newAnswers
    })
  }, [])

  const nextQuestion = useCallback(() => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1)
    }
  }, [currentQuestionIndex, questions.length])

  const previousQuestion = useCallback(() => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(prev => prev - 1)
    }
  }, [currentQuestionIndex])

  const canGoNext = useMemo(() => {
    const currentAnswer = answers[currentQuestionIndex]
    return currentAnswer !== null && currentAnswer.most !== currentAnswer.least
  }, [answers, currentQuestionIndex])

  const isComplete = useMemo(() => {
    return answers.every(answer => answer !== null)
  }, [answers])

  const progress = useMemo(() => {
    const answeredCount = answers.filter(answer => answer !== null).length
    return Math.round((answeredCount / questions.length) * 100)
  }, [answers, questions.length])

  const getElapsedMinutes = useCallback(() => {
    return Math.round((Date.now() - startTime) / 60000)
  }, [startTime])

  const clearSavedState = useCallback(() => {
    localStorage.removeItem('disc-test-state')
  }, [])

  return {
    currentQuestionIndex,
    answers,
    setAnswer,
    nextQuestion,
    previousQuestion,
    canGoNext,
    isComplete,
    progress,
    getElapsedMinutes,
    clearSavedState
  }
}
