```typescript
export function calculateDISCScores(
  answers: DISCAnswer[],
  questions: DISCQuestion[]
): DISCScores {
  const rawScores = { D: 0, I: 0, S: 0, C: 0 }

  answers.forEach((answer, index) => {
    const question = questions[index]
    const mostOption = question.opcoes_resposta[answer.most]
    const leastOption = question.opcoes_resposta[answer.least]

    // Most = +2 pontos, Least = -1 ponto
    rawScores[mostOption.dimensao] += 2
    rawScores[leastOption.dimensao] -= 1
  })

  // Normalizar para escala 0-100
  // Pontuação máxima: 28 * 2 = 56
  // Pontuação mínima: 28 * -1 = -28
  // Range total: 84 pontos
  const normalizedScores: DISCScores = {
    D: Math.max(0, Math.min(100, Math.round((rawScores.D + 28) / 84 * 100))),
    I: Math.max(0, Math.min(100, Math.round((rawScores.I + 28) / 84 * 100))),
    S: Math.max(0, Math.min(100, Math.round((rawScores.S + 28) / 84 * 100))),
    C: Math.max(0, Math.min(100, Math.round((rawScores.C + 28) / 84 * 100)))
  }

  return normalizedScores
}

export function getDISCProfile(scores: DISCScores) {
  const sortedScores = Object.entries(scores)
    .sort(([,a], [,b]) => b - a)

  const primaryStyle = sortedScores[0][0] as keyof DISCScores
  const secondaryStyle = sortedScores[1][0] as keyof DISCScores
  const combinedProfile = `${primaryStyle}${secondaryStyle}`

  const styleDescriptions = {
    D: 'Dominância - Direto, orientado a resultados, decisivo',
    I: 'Influência - Sociável, comunicativo, persuasivo',
    S: 'Estabilidade - Paciente, leal, cooperativo',
    C: 'Conformidade - Analítico, preciso, organizado'
  }

  return {
    primaryStyle,
    secondaryStyle,
    combinedProfile,
    primaryDescription: styleDescriptions[primaryStyle],
    scores: sortedScores.map(([style, score]) => ({
      style: style as keyof DISCScores,
      score,
      description: styleDescriptions[style as keyof DISCScores]
    }))
  }
}

export function validateDISCAnswers(
  answers: (DISCAnswer | null)[],
  expectedCount: number
): { isValid: boolean; errors: string[] } {
  const errors: string[] = []

  if (answers.length !== expectedCount) {
    errors.push(`Esperado ${expectedCount} respostas, encontrado ${answers.length}`)
  }

  const nullAnswers = answers
    .map((answer, index) => answer === null ? index + 1 : null)
    .filter(index => index !== null)

  if (nullAnswers.length > 0) {
    errors.push(`Questões não respondidas: ${nullAnswers.join(', ')}`)
  }

  answers.forEach((answer, index) => {
    if (answer && answer.most === answer.least) {
      errors.push(`Questão ${index + 1}: Most e Least não podem ser iguais`)
    }
  })

  return {
    isValid: errors.length === 0,
    errors
  }
}
