```typescript
export async function submitDISCTest({
  candidatoId,
  answers,
  questions,
  elapsedMinutes
}: {
  candidatoId: string
  answers: DISCAnswer[]
  questions: DISCQuestion[]
  elapsedMinutes: number
}) {
  // Validar respostas
  const validation = validateDISCAnswers(answers, 28)
  if (!validation.isValid) {
    throw new Error(`Respostas inválidas: ${validation.errors.join(', ')}`)
  }

  // Calcular pontuações
  const scores = calculateDISCScores(answers, questions)
  const profile = getDISCProfile(scores)

  try {
    // Iniciar transação
    const { data: resultado, error: resultError } = await supabase
      .from('resultados_disc')
      .insert([{
        candidato_id: candidatoId,
        pontuacao_d: scores.D,
        pontuacao_i: scores.I,
        pontuacao_s: scores.S,
        pontuacao_c: scores.C,
        estilo_primario: profile.primaryStyle,
        estilo_secundario: profile.secondaryStyle,
        perfil_combinado: profile.combinedProfile,
        respostas_completas: answers,
        data_conclusao: new Date().toISOString(),
        tempo_conclusao_minutos: elapsedMinutes
      }])
      .select()
      .single()

    if (resultError) throw resultError

    // Atualizar etapa do candidato
    const { error: updateError } = await supabase
      .from('candidatos')
      .update({
        etapa_atual: 'entrevista_online',
        progresso_processo: 42 // 3/7 etapas = 42%
      })
      .eq('id', candidatoId)

    if (updateError) throw updateError

    // Disparar webhook N8N
    try {
      await fetch('https://fernandocosta.app.n8n.cloud/webhook/disc-completo', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          candidato_id: candidatoId,
          resultado_id: resultado.id,
          pontuacoes: scores,
          perfil_primario: profile.primaryStyle,
          perfil_combinado: profile.combinedProfile,
          tempo_conclusao: elapsedMinutes
        })
      })
    } catch (webhookError) {
      console.error('Erro ao disparar webhook N8N:', webhookError)
      // Não falhar a submissão por erro de webhook
    }

    return {
      resultado,
      scores,
      profile
    }
  } catch (error) {
    console.error('Erro ao submeter teste DISC:', error)
    throw new Error('Falha ao salvar resultados do teste DISC')
  }
}

export async function checkExistingDISCResult(candidatoId: string) {
  const { data, error } = await supabase
    .from('resultados_disc')
    .select('id, data_conclusao')
    .eq('candidato_id', candidatoId)
    .single()

  if (error && error.code !== 'PGRST116') {
    throw error
  }

  return data
}
