export default function DISCTestPage() {
  const router = useRouter()
  const { canAccess, loading: accessLoading, error: accessError } = useDISCAccess()
  const { questions, loading: questionsLoading, error: questionsError } = useDISCQuestions()

  const [testPhase, setTestPhase] = useState<'intro' | 'test' | 'results'>('intro')
  const [submitting, setSubmitting] = useState(false)
  const [results, setResults] = useState<{
    scores: DISCScores
    profile: ReturnType<typeof getDISCProfile>
  } | null>(null)

  const {
    currentQuestionIndex,
    answers,
    setAnswer,
    nextQuestion,
    previousQuestion,
    canGoNext,
    isComplete,
    getElapsedMinutes,
    clearSavedState
  } = useDISCTest(questions)

  // Verificar acesso
  useEffect(() => {
    if (!accessLoading && !canAccess) {
      if (accessError?.includes('não autenticado')) {
        router.push('/login')
      } else {
        router.push('/dashboard')
      }
    }
  }, [accessLoading, canAccess, accessError, router])

  const handleStartTest = () => {
    setTestPhase('test')
  }

  const handleAnswerChange = (most: string, least: string) => {
    setAnswer(currentQuestionIndex, most, least)
  }

  const handleNext = async () => {
    if (currentQuestionIndex === questions.length - 1) {
      // Finalizar teste
      await handleSubmitTest()
    } else {
      nextQuestion()
    }
  }

  const handleSubmitTest = async () => {
    if (!isComplete) {
      alert('Por favor, responda todas as questões antes de finalizar.')
      return
    }

    setSubmitting(true)
    try {
      const { user } = await supabase.auth.getUser()
      if (!user.data.user) throw new Error('Usuário não autenticado')

      const { data: candidato } = await supabase
        .from('candidatos')
        .select('id')
        .eq('user_id', user.data.user.id)
        .single()

      if (!candidato) throw new Error('Candidato não encontrado')

      const result = await submitDISCTest({
        candidatoId: candidato.id,
        answers: answers.filter(Boolean) as DISCAnswer[],
        questions,
        elapsedMinutes: getElapsedMinutes()
      })

      setResults({
        scores: result.scores,
        profile: result.profile
      })

      clearSavedState()
      setTestPhase('results')
    } catch (error) {
      console.error('Erro ao submeter teste:', error)
      alert('Erro ao finalizar teste. Tente novamente.')
    } finally {
      setSubmitting(false)
    }
  }

  const handleReturnToDashboard = () => {
    router.push('/dashboard')
  }

  // Estados de carregamento
  if (accessLoading || questionsLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p>Carregando teste DISC...</p>
        </div>
      </div>
    )
  }

  // Estados de erro
  if (accessError || questionsError) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center max-w-md">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">Erro ao carregar teste</h1>
          <p className="text-gray-600 mb-4">{accessError || questionsError}</p>
          <button
            onClick={() => router.push('/dashboard')}
            className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700"
          >
            Voltar ao Dashboard
          </button>
        </div>
      </div>
    )
  }

  // Renderizar fase atual
  return (
    <div className="min-h-screen bg-gray-50">
      {testPhase === 'intro' && (
        <DISCIntroduction onStart={handleStartTest} />
      )}

      {testPhase === 'test' && (
        <DISCQuestion
          question={questions[currentQuestionIndex]}
          questionNumber={currentQuestionIndex + 1}
          totalQuestions={questions.length}
          answer={answers[currentQuestionIndex]}
          onAnswerChange={handleAnswerChange}
          onNext={handleNext}
          onPrevious={previousQuestion}
          canGoNext={canGoNext}
        />
      )}

      {testPhase === 'results' && results && (
        <DISCResults
          scores={results.scores}
          profile={results.profile}
          onReturnToDashboard={handleReturnToDashboard}
        />
      )}

      {/* Overlay de submissão */}
      {submitting && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p>Finalizando teste...</p>
          </div>
        </div>
      )}
    </div>
  )
}
