```typescript
interface UseImagePreloaderProps {
  imageUrls: string[]
}

interface UseImagePreloaderReturn {
  isLoading: boolean
  progress: number
  error: string | null
  preloadImages: () => Promise<void>
}

export function useImagePreloader({ imageUrls }: UseImagePreloaderProps): UseImagePreloaderReturn {
  const [isLoading, setIsLoading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [error, setError] = useState<string | null>(null)

  const preloadImages = async () => {
    setIsLoading(true)
    setError(null)
    let loadedCount = 0

    const promises = imageUrls.map(url => {
      return new Promise((resolve, reject) => {
        const img = new Image()
        img.onload = () => {
          loadedCount++
          setProgress((loadedCount / imageUrls.length) * 100)
          resolve(url)
        }
        img.onerror = () => reject(new Error(`Failed to load ${url}`))
        img.src = url
      })
    })

    try {
      await Promise.all(promises)
      setIsLoading(false)
    } catch (err) {
      setError('Erro ao carregar imagens. Verifique sua conexão.')
      setIsLoading(false)
    }
  }

  return { isLoading, progress, error, preloadImages }
}
