// middleware/ravenAccess.ts
export async function validateRavenAccess(candidatoId: string) {
  const { data: candidato } = await supabase
    .from('candidatos')
    .select('etapa_atual')
    .eq('id', candidatoId)
    .single()

  if (!candidato) {
    throw new Error('Candidato não encontrado')
  }

  if (candidato.etapa_atual !== 'raven') {
    throw new Error('Este teste estará disponível após completar a entrevista online')
  }

  // Verificar se já completou o teste
  const { data: resultado } = await supabase
    .from('resultados_raven')
    .select('id')
    .eq('candidato_id', candidatoId)
    .single()

  if (resultado) {
    throw new Error('Você já completou este teste. Resultados em análise.')
  }

  return true
}

// Componente de proteção
export function RavenTestGuard({ children }: { children: React.ReactNode }) {
  const [accessStatus, setAccessStatus] = useState<'loading' | 'allowed' | 'denied'>('loading')
  const [errorMessage, setErrorMessage] = useState('')

  useEffect(() => {
    validateRavenAccess(candidatoId)
      .then(() => setAccessStatus('allowed'))
      .catch(err => {
        setAccessStatus('denied')
        setErrorMessage(err.message)
      })
  }, [])

  if (accessStatus === 'loading') return <LoadingSpinner />
  if (accessStatus === 'denied') return <AccessDenied message={errorMessage} />

  return <>{children}</>
}
