Implementar funções de cálculo de pontuação:

```typescript
// types/raven.ts
interface RavenResults {
  rawScore: number
  percentile: number
  classification: string
  scoresBySet: {
    A: number
    B: number
    C: number
    D: number
    E: number
  }
  totalTimeMinutes: number
  timePerQuestion: number[]
  skippedCount: number
}

// utils/ravenScoring.ts
export function calculateRavenScore(
  answers: (number | null)[],
  questions: RavenQuestion[],
  timePerQuestion: number[]
): RavenResults {
  let rawScore = 0
  const scoresBySet = { A: 0, B: 0, C: 0, D: 0, E: 0 }
  let skippedCount = 0

  answers.forEach((answer, index) => {
    if (answer === null) {
      skippedCount++
      return
    }

    if (answer === questions[index].resposta_correta) {
      rawScore++
      scoresBySet[questions[index].conjunto as keyof typeof scoresBySet]++
    }
  })

  const totalTimeMinutes = Math.round(timePerQuestion.reduce((sum, time) => sum + time, 0) / 60000)
  const percentile = convertToPercentile(rawScore)
  const classification = getClassification(percentile)

  return {
    rawScore,
    percentile,
    classification,
    scoresBySet,
    totalTimeMinutes,
    timePerQuestion,
    skippedCount
  }
}

// Tabela normativa simplificada (baseada em dados brasileiros)
const PERCENTILE_TABLE = {
  // Raw score -> Percentile
  0: 1, 5: 5, 10: 10, 15: 15, 20: 20, 25: 25, 30: 35, 35: 45,
  40: 55, 45: 65, 50: 75, 55: 85, 60: 95
}

export function convertToPercentile(rawScore: number): number {
  // Interpolação linear entre pontos da tabela
  const scores = Object.keys(PERCENTILE_TABLE).map(Number).sort((a, b) => a - b)

  if (rawScore <= scores[0]) return PERCENTILE_TABLE[scores[0] as keyof typeof PERCENTILE_TABLE]
  if (rawScore >= scores[scores.length - 1]) return PERCENTILE_TABLE[scores[scores.length - 1] as keyof typeof PERCENTILE_TABLE]

  // Encontrar pontos para interpolação
  for (let i = 0; i < scores.length - 1; i++) {
    if (rawScore >= scores[i] && rawScore <= scores[i + 1]) {
      const x1 = scores[i], y1 = PERCENTILE_TABLE[x1 as keyof typeof PERCENTILE_TABLE]
      const x2 = scores[i + 1], y2 = PERCENTILE_TABLE[x2 as keyof typeof PERCENTILE_TABLE]

      // Interpolação linear: y = y1 + (y2-y1) * (x-x1)/(x2-x1)
      return Math.round(y1 + (y2 - y1) * (rawScore - x1) / (x2 - x1))
    }
  }

  return 50 // fallback
}

export function getClassification(percentile: number): string {
  if (percentile <= 25) return 'Abaixo da média'
  if (percentile <= 40) return 'Média baixa'
  if (percentile <= 60) return 'Média'
  if (percentile <= 75) return 'Média alta'
  return 'Acima da média'
}
