// services/ravenService.ts
export async function saveRavenResults(
  candidatoId: string,
  results: RavenResults,
  answers: (number | null)[]
) {
  try {
    // Salvar resultados no banco
    const { data: resultado, error } = await supabase
      .from('resultados_raven')
      .insert([{
        candidato_id: candidatoId,
        pontuacao_bruta: results.rawScore,
        pontuacao_percentil: results.percentile,
        classificacao: results.classification,
        pontuacao_conjunto_a: results.scoresBySet.A,
        pontuacao_conjunto_b: results.scoresBySet.B,
        pontuacao_conjunto_c: results.scoresBySet.C,
        pontuacao_conjunto_d: results.scoresBySet.D,
        pontuacao_conjunto_e: results.scoresBySet.E,
        respostas_completas: answers,
        tempo_total_minutos: results.totalTimeMinutes,
        tempo_por_questao: results.timePerQuestion,
        questoes_puladas: results.skippedCount,
        data_conclusao: new Date().toISOString()
      }])
      .select()
      .single()

    if (error) throw error

    // Atualizar etapa do candidato
    await supabase
      .from('candidatos')
      .update({
        etapa_atual: 'cultura', // Próxima etapa
        progresso_processo: 71 // 5/7 etapas = ~71%
      })
      .eq('id', candidatoId)

    // Disparar webhook N8N
    await fetch('https://fernandocosta.app.n8n.cloud/webhook/raven-completo', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        candidato_id: candidatoId,
        resultado_id: resultado.id,
        pontuacao_bruta: results.rawScore,
        percentil: results.percentile,
        classificacao: results.classification,
        tempo_total: results.totalTimeMinutes,
        data_conclusao: new Date().toISOString()
      })
    })

    return resultado
  } catch (error) {
    console.error('Erro ao salvar resultados Raven:', error)
    throw new Error('Falha ao salvar resultados. Tente novamente.')
  }
}

// Hook para gerenciar o processo completo
export function useRavenTestCompletion() {
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const completeTest = async (
    candidatoId: string,
    answers: (number | null)[],
    questions: RavenQuestion[],
    timePerQuestion: number[]
  ) => {
    setIsSubmitting(true)
    setError(null)

    try {
      const results = calculateRavenScore(answers, questions, timePerQuestion)
      const savedResult = await saveRavenResults(candidatoId, results, answers)

      return { results, savedResult }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erro desconhecido')
      throw err
    } finally {
      setIsSubmitting(false)
    }
  }

  return { completeTest, isSubmitting, error }
}
