        user.id,
        answers,
        questions,
        timePerQuestion
      )

      setResults(testResults)
      setTestState('results')
    } catch (error) {
      console.error('Erro ao finalizar teste:', error)
    }
  }

  const handleGoToQuestion = (questionIndex: number) => {
    setCurrentQuestionIndex(questionIndex)
    setTestState('testing')
  }

  const handleReturnToDashboard = () => {
    window.location.href = '/dashboard'
  }

  // Render based on current state
  return (
    <RavenTestGuard>
      <div className="min-h-screen bg-gray-50">
        {testState === 'loading' && (
          <div className="flex items-center justify-center min-h-screen">
            <LoadingSpinner />
          </div>
        )}

        {testState === 'intro' && (
          <RavenIntroduction onStartTest={handleStartTest} />
        )}

        {testState === 'preloading' && (
          <div className="flex flex-col items-center justify-center min-h-screen">
            <h2 className="text-xl font-semibold mb-4">Carregando teste...</h2>
            <div className="w-96 bg-gray-200 rounded-full h-4 mb-4">
              <div 
                className="bg-blue-600 h-4 rounded-full transition-all duration-300" 
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-sm text-gray-600">Carregando imagens: {Math.round(progress)}%</p>
            {preloadError && (
              <p className="text-red-600 mt-2">{preloadError}</p>
            )}
          </div>
        )}

        {testState === 'testing' && (
          <RavenTestInterface
            questions={questions}
            currentQuestionIndex={currentQuestionIndex}
            answers={answers}
            skippedQuestions={skippedQuestions}
            timePerQuestion={timePerQuestion}
            onAnswerChange={setAnswers}
            onQuestionChange={setCurrentQuestionIndex}
            onSkippedChange={setSkippedQuestions}
            onTimeChange={setTimePerQuestion}
            onShowReview={() => setTestState('review')}
          />
        )}

        {testState === 'review' && (
          <RavenReviewScreen
            questions={questions}
            answers={answers}
            skippedQuestions={skippedQuestions}
            onGoToQuestion={handleGoToQuestion}
            onFinishTest={handleTestComplete}
            onContinueAnswering={() => setTestState('testing')}
          />
        )}

        {testState === 'results' && results && (
          <RavenResultsScreen
            results={results}
            onReturnToDashboard={handleReturnToDashboard}
          />
        )}

        {(submitError || preloadError) && (
          <div className="fixed bottom-4 right-4 bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
            {submitError || preloadError}
          </div>
        )}

        {isSubmitting && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white p-6 rounded-lg">
              <LoadingSpinner />
              <p className="mt-2 text-center">Salvando resultados...</p>
            </div>
          </div>
        )}
      </div>
    </RavenTestGuard>
  )
}
