import jsPDF from 'jspdf'
import html2canvas from 'html2canvas'

export class PDFGenerator {
  static async gerarRelatorioCandidato(candidato: Candidato, resultados: AllResults) {
    const pdf = new jsPDF('p', 'mm', 'a4')
    let yPosition = 20

    // Página 1: Capa
    pdf.setFontSize(24)
    pdf.text('Relatório de Testes Psicométricos', 20, yPosition)
    yPosition += 15

    pdf.setFontSize(16)
    pdf.text(`Candidato: ${candidato.nome_completo}`, 20, yPosition)
    yPosition += 10
    pdf.text(`Data: ${format(new Date(), 'dd/MM/yyyy')}`, 20, yPosition)
    yPosition += 10
    pdf.text(`Vaga: ${candidato.vaga?.titulo || 'N/A'}`, 20, yPosition)

    // Sumário Executivo
    pdf.addPage()
    yPosition = 20
    pdf.setFontSize(18)
    pdf.text('Sumário Executivo', 20, yPosition)
    yPosition += 15

    if (resultados.analise_ia) {
      pdf.setFontSize(12)
      const resumoLines = pdf.splitTextToSize(resultados.analise_ia.resumo_executivo, 170)
      pdf.text(resumoLines, 20, yPosition)
      yPosition += resumoLines.length * 5 + 10

      pdf.text(`Recomendação: ${resultados.analise_ia.recomendacao}`, 20, yPosition)
      yPosition += 8
      pdf.text(`Confiança: ${resultados.analise_ia.score_confianca}%`, 20, yPosition)
    }

    // Página 2: Big Five
    await this.adicionarPaginaBigFive(pdf, resultados.big_five)

    // Página 3: DISC
    await this.adicionarPaginaDISC(pdf, resultados.disc)

    // Página 4: Raven
    await this.adicionarPaginaRaven(pdf, resultados.raven)

    // Página 5: Análise de Match (se disponível)
    if (resultados.analise_ia && candidato.vaga) {
      await this.adicionarPaginaMatch(pdf, resultados.analise_ia, candidato.vaga)
    }

    return pdf
  }

  static async adicionarPaginaBigFive(pdf: jsPDF, resultados: ResultadosBigFive) {
    pdf.addPage()
    let yPosition = 20

    pdf.setFontSize(18)
    pdf.text('Big Five - Personalidade', 20, yPosition)
    yPosition += 15

    // Capturar radar chart
    const radarElement = document.getElementById('big-five-radar-pdf')
    if (radarElement) {
      const canvas = await html2canvas(radarElement)
      const imgData = canvas.toDataURL('image/png')
      pdf.addImage(imgData, 'PNG', 20, yPosition, 170, 100)
      yPosition += 110
    }

    // Adicionar scores textuais
    pdf.setFontSize(12)
    const dimensoes = [
      { nome: 'Abertura a Experiências', valor: resultados.abertura },
      { nome: 'Conscienciosidade', valor: resultados.conscienciosidade },
      { nome: 'Extroversão', valor: resultados.extroversao },
      { nome: 'Amabilidade', valor: resultados.amabilidade },
      { nome: 'Neuroticismo', valor: resultados.neuroticismo }
    ]

    dimensoes.forEach(dimensao => {
      pdf.text(`${dimensao.nome}: ${dimensao.valor}/100`, 20, yPosition)
      yPosition += 8
    })
  }

  static async adicionarPaginaDISC(pdf: jsPDF, resultados: ResultadosDISC) {
    pdf.addPage()
    let yPosition = 20

    pdf.setFontSize(18)
    pdf.text('DISC - Comportamento', 20, yPosition)
    yPosition += 15

    // Capturar bar chart
    const discElement = document.getElementById('disc-chart-pdf')
    if (discElement) {
      const canvas = await html2canvas(discElement)
      const imgData = canvas.toDataURL('image/png')
      pdf.addImage(imgData, 'PNG', 20, yPosition, 170, 80)
      yPosition += 90
    }

    // Perfil comportamental
    pdf.setFontSize(14)
    pdf.text(`Perfil: ${resultados.perfil_primario}`, 20, yPosition)
    yPosition += 10

    pdf.setFontSize(12)
    pdf.text(`Dominância: ${resultados.dominancia}/100`, 20, yPosition)
    yPosition += 6
    pdf.text(`Influência: ${resultados.influencia}/100`, 20, yPosition)
    yPosition += 6
    pdf.text(`Estabilidade: ${resultados.estabilidade}/100`, 20, yPosition)
    yPosition += 6
    pdf.text(`Conformidade: ${resultados.conformidade}/100`, 20, yPosition)
  }

  static async adicionarPaginaRaven(pdf: jsPDF, resultados: ResultadosRaven) {
    pdf.addPage()
    let yPosition = 20

    pdf.setFontSize(18)
    pdf.text('Raven - Raciocínio Lógico', 20, yPosition)
    yPosition += 15

    pdf.setFontSize(14)
    pdf.text(`Pontuação: ${resultados.pontuacao_total}/60 (${Math.round(resultados.pontuacao_total/60*100)}%)`, 20, yPosition)
    yPosition += 10
    pdf.text(`Percentil: ${resultados.percentil}º`, 20, yPosition)
    yPosition += 10
    pdf.text(`Classificação: ${resultados.classificacao}`, 20, yPosition)
    yPosition += 15

    // Desempenho por conjunto
    pdf.setFontSize(12)
    pdf.text('Desempenho por Conjunto:', 20, yPosition)
    yPosition += 10

    Object.entries(resultados.desempenho_conjuntos).forEach(([conjunto, acertos]) => {
      pdf.text(`Conjunto ${conjunto}: ${acertos}/12 (${Math.round(acertos/12*100)}%)`, 30, yPosition)
      yPosition += 6
    })
  }
}
