Implementar hooks personalizados para queries de candidatos com TanStack Query. Criar índices no banco para otimização. Implementar paginação, ordenação e filtros básicos.

Pseudo-código:
```typescript
// hooks/useCandidatos.ts
export function useCandidatos(filters: FilterState, pagination: PaginationState) {
  return useQuery({
    queryKey: ['candidatos', filters, pagination],
    queryFn: async () => {
      let query = supabase
        .from('candidatos')
        .select(`
          id, nome_completo, email, telefone, etapa_atual,
          match_score, created_at, updated_at,
          tags_candidato(tags(*))
        `, { count: 'exact' })
        .range(pagination.offset, pagination.offset + pagination.limit - 1)

      if (filters.search) {
        query = query.or(`
          nome_completo.ilike.%${filters.search}%,
          email.ilike.%${filters.search}%,
          telefone.ilike.%${filters.search}%,
          cpf.ilike.%${filters.search}%
        `)
      }

      if (filters.stages.length > 0) {
        query = query.in('etapa_atual', filters.stages)
      }

      return query
    }
  })
}

// SQL para índices
CREATE INDEX idx_candidatos_etapa ON candidatos(etapa_atual);
CREATE INDEX idx_candidatos_match ON candidatos(match_score DESC);
