Criar componente de busca com debounce de 300ms que pesquisa em múltiplos campos. Destacar termos encontrados nos resultados e mostrar contador de resultados.

Pseudo-código:
```typescript
// components/SearchInput.tsx
function SearchInput({ value, onChange, placeholder, debounceMs = 300 }) {
  const [localValue, setLocalValue] = useState(value)
  const debouncedValue = useDebounce(localValue, debounceMs)

  useEffect(() => {
    onChange(debouncedValue)
  }, [debouncedValue, onChange])

  return (
    <div className="relative">
      <input
        type="text"
        value={localValue}
        onChange={(e) => setLocalValue(e.target.value)}
        placeholder={placeholder}
        className="w-full pl-10 pr-4 py-2 border rounded-lg"
      />
      <SearchIcon className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
      {localValue && (
        <button
          onClick={() => setLocalValue('')}
          className="absolute right-3 top-2.5"
        >
          <XIcon className="h-5 w-5 text-gray-400" />
        </button>
      )}
    </div>
  )
}

// Hook para debounce
function useDebounce(value: string, delay: number) {
  const [debouncedValue, setDebouncedValue] = useState(value)

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => clearTimeout(handler)
  }, [value, delay])

  return debouncedValue
}
