Implementar paginação com diferentes tamanhos de página, indicadores de carregamento e otimizações para grandes volumes de dados.

Pseudo-código:
```typescript
// components/Pagination.tsx
function Pagination({ 
  currentPage, 
  totalPages, 
  totalItems, 
  itemsPerPage, 
  onPageChange, 
  onItemsPerPageChange 
}) {
  const startItem = (currentPage - 1) * itemsPerPage + 1
  const endItem = Math.min(currentPage * itemsPerPage, totalItems)

  return (
    <div className="flex items-center justify-between mt-6">
      <div className="flex items-center gap-4">
        <span className="text-sm text-gray-600">
          Mostrando {startItem}-{endItem} de {totalItems} candidatos
        </span>

        <select
          value={itemsPerPage}
          onChange={(e) => onItemsPerPageChange(Number(e.target.value))}
          className="border rounded px-2 py-1 text-sm"
        >
          <option value={20}>20 por página</option>
          <option value={50}>50 por página</option>
          <option value={100}>100 por página</option>
          <option value={200}>200 por página</option>
        </select>
      </div>

      <div className="flex items-center gap-2">
        <Button
          disabled={currentPage === 1}
          onClick={() => onPageChange(currentPage - 1)}
          size="sm"
        >
          ← Anterior
        </Button>

        <div className="flex gap-1">
          {getPaginationNumbers(currentPage, totalPages).map(page => (
            <Button
              key={page}
              variant={page === currentPage ? 'primary' : 'ghost'}
              size="sm"
              onClick={() => typeof page === 'number' && onPageChange(page)}
            >
              {page}
            </Button>
          ))}
        </div>

        <Button
          disabled={currentPage === totalPages}
          onClick={() => onPageChange(currentPage + 1)}
          size="sm"
        >
          Próxima →
        </Button>
      </div>
    </div>
  )
}

// utils/pagination.ts
function getPaginationNumbers(current: number, total: number): (number | string)[] {
  const delta = 2
  const range = []
  const rangeWithDots = []

  for (let i = Math.max(2, current - delta); i <= Math.min(total - 1, current + delta); i++) {
    range.push(i)
  }

  if (current - delta > 2) {
    rangeWithDots.push(1, '...')
  } else {
    rangeWithDots.push(1)
  }

  rangeWithDots.push(...range)

  if (current + delta < total - 1) {
    rangeWithDots.push('...', total)
  } else {
    rangeWithDots.push(total)
  }

  return rangeWithDots
}

// hooks/usePagination.ts
export function usePagination(initialPage = 1, initialItemsPerPage = 20) {
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [itemsPerPage, setItemsPerPage] = useState(initialItemsPerPage)

  const offset = (currentPage - 1) * itemsPerPage

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handleItemsPerPageChange = (newItemsPerPage: number) => {
    setItemsPerPage(newItemsPerPage)
    setCurrentPage(1) // Reset to first page
  }

  return {
    currentPage,
    itemsPerPage,
    offset,
    handlePageChange,
    handleItemsPerPageChange
  }
}
