function ResponsiveTable({ screenSize }: { screenSize: 'mobile' | 'tablet' | 'desktop' }) {
  const getVisibleColumns = () => {
    switch (screenSize) {
      case 'mobile':
        return ['nome_completo', 'etapa_atual', 'actions']
      case 'tablet':
        return ['nome_completo', 'email', 'etapa_atual', 'match_score', 'actions']
      case 'desktop':
      default:
        return ['select', 'nome_completo', 'email', 'telefone', 'etapa_atual', 'match_score', 'testes', 'created_at', 'actions']
    }
  }

  const visibleColumns = getVisibleColumns()
  const columns = ALL_COLUMNS.filter(col => visibleColumns.includes(col.id))

  return (
    <div className={screenSize === 'mobile' ? 'px-2' : 'px-4'}>
      <CandidateTable columns={columns} />
    </div>
  )
}
