Implementar função de aprovação conforme especificação:

```typescript
const stageFlow = {
  triagem: 'big_five',
  big_five: 'disc',
  disc: 'entrevista_online',
  entrevista_online: 'raven',
  raven: 'cultura',
  cultura: 'entrevista_presencial',
  entrevista_presencial: 'aprovado'
};

function getNextStage(currentStage: string): string {
  return stageFlow[currentStage] || 'aprovado';
}

function calculateProgress(stage: string): number {
  const stages = Object.keys(stageFlow);
  const currentIndex = stages.indexOf(stage);
  return Math.round(((currentIndex + 1) / stages.length) * 100);
}

async function approveCandidate(
  candidatoId: string, 
  notes?: string, 
  sendEmail: boolean = true
) {
  try {
    // 1. Get candidate data
    const { data: candidate } = await supabase
      .from('candidatos')
      .select('*, vagas(*)')
      .eq('id', candidatoId)
      .single();

    if (!candidate) throw new Error('Candidato não encontrado');

    const nextStage = getNextStage(candidate.etapa_atual);
    const progress = calculateProgress(nextStage);

    // 2. Update candidate stage
    const { error: updateError } = await supabase
      .from('candidatos')
      .update({
        etapa_atual: nextStage,
        progresso_processo: progress,
        aprovado_por: currentUser.id,
        aprovado_em: new Date().toISOString()
      })
      .eq('id', candidatoId);

    if (updateError) throw updateError;

    // 3. Log decision
    const { error: logError } = await supabase
      .from('decisoes_rh')
      .insert({
        candidato_id: candidatoId,
        tipo_decisao: 'aprovacao',
        etapa_origem: candidate.etapa_atual,
        etapa_destino: nextStage,
        usuario_rh_id: currentUser.id,
        notas_internas: notes,
        email_enviado: sendEmail,
        template_email_usado: sendEmail ? 'aprovacao' : null
      });

    if (logError) throw logError;

    // 4. Send email notification
    if (sendEmail) {
      await sendApprovalEmail(candidatoId, nextStage);
    }

    // 5. Log activity
    await logActivity({
      type: 'aprovacao',
      candidato_id: candidatoId,
      usuario_rh_id: currentUser.id,
      detalhes: `Aprovado para ${nextStage}`
    });

    showSuccess('Candidato aprovado com sucesso!');

  } catch (error) {
    console.error('Erro ao aprovar candidato:', error);
    showError('Erro ao processar aprovação. Tente novamente.');
    throw error;
  }
}
```

