async function rejectCandidate(
  candidatoId: string,
  reason: string,
  details: string,
  emailTemplate: string = 'rejeicao_padrao',
  sendEmail: boolean = true
) {
  try {
    // 1. Get candidate data
    const { data: candidate } = await supabase
      .from('candidatos')
      .select('*, vagas(*)')
      .eq('id', candidatoId)
      .single();

    if (!candidate) throw new Error('Candidato não encontrado');

    // 2. Update candidate status
    const { error: updateError } = await supabase
      .from('candidatos')
      .update({
        status_processo: 'rejeitado',
        data_rejeicao: new Date().toISOString(),
        rejeitado_por: currentUser.id
      })
      .eq('id', candidatoId);

    if (updateError) throw updateError;

    // 3. Log decision
    const { error: logError } = await supabase
      .from('decisoes_rh')
      .insert({
        candidato_id: candidatoId,
        tipo_decisao: 'rejeicao',
        etapa_origem: candidate.etapa_atual,
        etapa_destino: null,
        motivo_rejeicao: reason,
        detalhes_rejeicao: details,
        usuario_rh_id: currentUser.id,
        email_enviado: sendEmail,
        template_email_usado: sendEmail ? emailTemplate : null
      });

    if (logError) throw logError;

    // 4. Send rejection email
    if (sendEmail) {
      await sendRejectionEmail(candidatoId, reason, details, emailTemplate);
    }

    // 5. Log activity
    await logActivity({
      type: 'rejeicao',
      candidato_id: candidatoId,
      usuario_rh_id: currentUser.id,
      detalhes: `Rejeitado: ${reason}`
    });

    showSuccess('Candidato rejeitado com sucesso!');

