Implementar aprovação/rejeição em lote:

```typescript
interface BulkActionModalProps {
  isOpen: boolean;
  selectedCandidates: Candidato[];
  action: 'approve' | 'reject';
  onConfirm: (options: BulkActionOptions) => void;
  onCancel: () => void;
}

interface BulkActionOptions {
  sendEmails: boolean;
  rejectionReason?: string;
  rejectionDetails?: string;
}

const BulkActionModal: React.FC<BulkActionModalProps> = ({
  isOpen,
  selectedCandidates,
  action,
  onConfirm,
  onCancel
}) => {
  const [sendEmails, setSendEmails] = useState(true);
  const [rejectionReason, setRejectionReason] = useState('');
  const [rejectionDetails, setRejectionDetails] = useState('');

  const groupedByStage = selectedCandidates.reduce((acc, candidate) => {
    const stage = candidate.etapa_atual;
    if (!acc[stage]) acc[stage] = [];
    acc[stage].push(candidate);
    return acc;
  }, {} as Record<string, Candidato[]>);

  return (
    <Modal isOpen={isOpen} onClose={onCancel}>
      <div className="p-6">
        <h2>
          {action === 'approve' ? 'Aprovar' : 'Rejeitar'} {selectedCandidates.length} candidatos em lote
        </h2>

        <div className="mt-4">
          {action === 'approve' ? (
            <div>
              <p>Todos os candidatos serão movidos para a próxima etapa:</p>
              {Object.entries(groupedByStage).map(([stage, candidates]) => (
                <p key={stage}>
                  • {candidates.length} candidatos em {stage} → {getNextStage(stage)}
                </p>
              ))}
            </div>
          ) : (
            <div>
              <label className="required">Motivo (aplicado a todos):</label>
              <Select
                value={rejectionReason}
                onChange={setRejectionReason}
                options={rejectionReasons.filter(r => r !== 'Outro (especificar abaixo)')}
              />

              <label className="required mt-4">Detalhes adicionais:</label>
              <Textarea
                value={rejectionDetails}
                onChange={setRejectionDetails}
                minLength={20}
              />
            </div>
          )}
        </div>

        <div className="mt-4">
          <Checkbox
            checked={sendEmails}
            onChange={setSendEmails}
            label={`Enviar email de ${action === 'approve' ? 'aprovação' : 'rejeição'} para todos`}
          />
        </div>

        <div className="flex justify-end gap-2 mt-6">
          <Button variant="secondary" onClick={onCancel}>
            Cancelar
          </Button>
          <Button
            variant={action === 'approve' ? 'primary' : 'danger'}
            onClick={() => onConfirm({ sendEmails, rejectionReason, rejectionDetails })}
          >
            {action === 'approve' ? 'Aprovar' : 'Rejeitar'} {selectedCandidates.length} candidatos
          </Button>
        </div>
      </div>
    </Modal>
  );
};

async function processBulkAction(
  candidateIds: string[],
  action: 'approve' | 'reject',
  options: BulkActionOptions,
  onProgress: (current: number, total: number) => void
) {
  const results = { success: 0, failed: 0, errors: [] as string[] };

  for (let i = 0; i < candidateIds.length; i++) {
    const candidateId = candidateIds[i];
    onProgress(i + 1, candidateIds.length);

    try {
      if (action === 'approve') {
        await approveCandidate(candidateId, undefined, options.sendEmails);
      } else {
        await rejectCandidate(
          candidateId,
          options.rejectionReason!,
          options.rejectionDetails!,
          'rejeicao_padrao',
          options.sendEmails
        );
      }
      results.success++;
    } catch (error) {
      results.failed++;
      results.errors.push(`Erro ao processar candidato ${candidateId}`);
    }

    // Prevent overwhelming the system
    if (i < candidateIds.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }
  }

  return results;
}
```

Implementar sistema de permissões:

```typescript
type UserRole = 'rh_basico' | 'rh_avancado' | 'admin';
type Stage = 'triagem' | 'big_five' | 'disc' | 'entrevista_online' | 'raven' | 'cultura' | 'entrevista_presencial';

interface PermissionMatrix {
  canApprove: (role: UserRole, stage: Stage) => boolean;
  canReject: (role: UserRole, stage: Stage) => boolean;
  canBulkAction: (role: UserRole) => boolean;
  canReverseDecision: (role: UserRole) => boolean;
  canViewAuditTrail: (role: UserRole) => boolean;
}

const permissions: PermissionMatrix = {
  canApprove: (role: UserRole, stage: Stage): boolean => {
    if (role === 'admin') return true;
    if (role === 'rh_avancado' && stage !== 'entrevista_presencial') return true;
    if (role === 'rh_basico' && stage === 'triagem') return true;
    return false;
  },

  canReject: (role: UserRole, stage: Stage): boolean => {
    if (role === 'admin') return true;
    if (role === 'rh_avancado') return true;
    return false;
  },

  canBulkAction: (role: UserRole): boolean => {
    return role === 'rh_avancado' || role === 'admin';
  },

  canReverseDecision: (role: UserRole): boolean => {
    return role === 'admin';
  },

  canViewAuditTrail: (role: UserRole): boolean => {
    return role === 'rh_avancado' || role === 'admin';
  }
};

// Hook para verificar permissões
function usePermissions() {
  const { user } = useAuth();

  return {
    canApprove: (stage: Stage) => permissions.canApprove(user.role, stage),
    canReject: (stage: Stage) => permissions.canReject(user.role, stage),
    canBulkAction: () => permissions.canBulkAction(user.role),
    canReverseDecision: () => permissions.canReverseDecision(user.role),
    canViewAuditTrail: () => permissions.canViewAuditTrail(user.role)
  };
}

// Componente com verificação de permissões
const ApprovalButtons: React.FC<ApprovalButtonsProps> = ({ candidato, ...props }) => {
  const { canApprove, canReject } = usePermissions();

  const canApproveCandidate = canApprove(candidato.etapa_atual);
  const canRejectCandidate = canReject(candidato.etapa_atual);

  return (
    <div className="flex gap-2">
      {canApproveCandidate && (
        <Button
          variant="success"
          onClick={() => props.onApprove(candidato.id)}
          disabled={candidato.status_processo !== 'em_andamento'}
        >
          ✅ Aprovar
        </Button>
      )}

      {canRejectCandidate && (
        <Button
          variant="danger"
          onClick={() => props.onReject(candidato.id)}
          disabled={candidato.status_processo !== 'em_andamento'}
        >
          ❌ Rejeitar
        </Button>
