async function reverseDecision(
  decisaoId: string,
  reason: string,
  notifyCandidate: boolean = false
) {
  try {
    // 1. Get decision and candidate data
    const { data: decision } = await supabase
      .from('decisoes_rh')
      .select('*, candidatos(*)')
      .eq('id', decisaoId)
      .single();

    if (!decision) throw new Error('Decisão não encontrada');

    const candidato = decision.candidatos;

    // 2. Restore candidate to original stage
    const { error: updateError } = await supabase
      .from('candidatos')
      .update({
        etapa_atual: decision.etapa_origem,
        status_processo: 'em_andamento',
        progresso_processo: calculateProgress(decision.etapa_origem)
      })
      .eq('id', candidato.id);

    if (updateError) throw updateError;

    // 3. Mark original decision as reversed
    const { error: reversalError } = await supabase
      .from('decisoes_rh')
      .update({
        revertida: true,
        revertida_por: currentUser.id,
        data_reversao: new Date().toISOString(),
        motivo_reversao: reason
      })
      .eq('id', decisaoId);

    if (reversalError) throw reversalError;

    // 4. Log new reversal decision
    await supabase
      .from('decisoes_rh')
      .insert({
        candidato_id: candidato.id,
        tipo_decisao: 'reversao',
        etapa_origem: candidato.etapa_atual,
        etapa_destino: decision.etapa_origem,
        usuario_rh_id: currentUser.id,
        notas_internas: reason,
        email_enviado: notifyCandidate
      });

    // 5. Send notification if requested
    if (notifyCandidate) {
      await sendReversalEmail(candidato.id, decision.tipo_decisao);
    }

    showSuccess('Decisão revertida com sucesso!');

  } catch (error) {
    console.error('Erro ao reverter decisão:', error);
    showError('Erro ao reverter decisão. Tente novamente.');
    throw error;
  }
}
