interface AuditDashboardProps {
  userRole: UserRole;
}

const AuditDashboard: React.FC<AuditDashboardProps> = ({ userRole }) => {
  const [decisions, setDecisions] = useState<DecisaoRH[]>([]);
  const [filters, setFilters] = useState({
    tipo: 'todas',
    periodo: 'ultimo_mes',
    usuario: 'todos'
  });
  const [loading, setLoading] = useState(false);

  const { canViewAuditTrail } = usePermissions();

  if (!canViewAuditTrail()) {
    return <div>Acesso negado</div>;
  }

  const fetchDecisions = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('decisoes_rh')
        .select(`
          *,
          candidatos(nome_completo, email),
          usuarios_rh(nome)
        `)
        .order('data_decisao', { ascending: false });

      if (filters.tipo !== 'todas') {
        query = query.eq('tipo_decisao', filters.tipo);
      }

      if (filters.periodo === 'ultimo_mes') {
        const lastMonth = new Date();
        lastMonth.setMonth(lastMonth.getMonth() - 1);
        query = query.gte('data_decisao', lastMonth.toISOString());
      }

      if (filters.usuario !== 'todos') {
        query = query.eq('usuario_rh_id', filters.usuario);
      }

      const { data, error } = await query;

      if (error) throw error;
      setDecisions(data || []);
    } catch (error) {
      console.error('Erro ao carregar decisões:', error);
      showError('Erro ao carregar histórico');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDecisions();
  }, [filters]);

  const exportReport = async () => {
    try {
