        <Select
          label="Tipo:"
          value={filters.tipo}
          onChange={(value) => setFilters(prev => ({ ...prev, tipo: value }))}
          options={[
            { value: 'todas', label: 'Todas' },
            { value: 'aprovacao', label: 'Aprovações' },
            { value: 'rejeicao', label: 'Rejeições' },
