```tsx
interface RejectionAnalyticsProps {
  period: 'last_30_days' | 'last_3_months' | 'last_year';
}

const RejectionAnalytics: React.FC<RejectionAnalyticsProps> = ({ period }) => {
  const [analytics, setAnalytics] = useState<RejectionAnalytics | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchAnalytics = async () => {
    try {
      const periodDays = {
        last_30_days: 30,
        last_3_months: 90,
        last_year: 365
      };

      const startDate = new Date();
      startDate.setDate(startDate.getDate() - periodDays[period]);

      // Get rejection data
      const { data: rejections } = await supabase
        .from('decisoes_rh')
        .select(`
          *,
          candidatos(vagas(titulo)),
          usuarios_rh(nome)
        `)
        .eq('tipo_decisao', 'rejeicao')
        .gte('data_decisao', startDate.toISOString());

      // Process analytics
      const totalRejections = rejections?.length || 0;

      // By reason
      const byReason = rejections?.reduce((acc, rejection) => {
        const reason = rejection.motivo_rejeicao;
        acc[reason] = (acc[reason] || 0) + 1;
        return acc;
      }, {} as Record<string, number>) || {};

      // By stage
      const byStage = rejections?.reduce((acc, rejection) => {
        const stage = rejection.etapa_origem;
        acc[stage] = (acc[stage] || 0) + 1;
        return acc;
      }, {} as Record<string, number>) || {};

      // By recruiter
      const byRecruiter = rejections?.reduce((acc, rejection) => {
        const recruiter = rejection.usuarios_rh.nome;
        acc[recruiter] = (acc[recruiter] || 0) + 1;
        return acc;
      }, {} as Record<string, number>) || {};

      // By job
      const byJob = rejections?.reduce((acc, rejection) => {
        const job = rejection.candidatos.vagas.titulo;
        acc[job] = (acc[job] || 0) + 1;
        return acc;
      }, {} as Record<string, number>) || {};

      setAnalytics({
        totalRejections,
        byReason: Object.entries(byReason)
          .map(([reason, count]) => ({ reason, count, percentage: (count / totalRejections) * 100 }))
          .sort((a, b) => b.count - a.count),
        byStage: Object.entries(byStage)
          .map(([stage, count]) => ({ stage, count, percentage: (count / totalRejections) * 100 }))
          .sort((a, b) => b.count - a.count),
        byRecruiter: Object.entries(byRecruiter)
          .map(([recruiter, count]) => ({ recruiter, count, percentage: (count / totalRejections) * 100 }))
          .sort((a, b) => b.count - a.count),
        byJob: Object.entries(byJob)
          .map(([job, count]) => ({ job, count, percentage: (count / totalRejections) * 100 }))
          .sort((a, b) => b.count - a.count)
      });

    } catch (error) {
      console.error('Erro ao carregar analytics:', error);
      showError('Erro ao carregar analytics');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAnalytics();
  }, [period]);

  if (loading) {
    return <div className="flex justify-center py-8"><Spinner /></div>;
  }

  if (!analytics) {
    return <div>Erro ao carregar dados</div>;
  }

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1>Análise de Rejeições - {getPeriodLabel(period)}</h1>
        <p className="text-lg font-semibold">Total de rejeições: {analytics.totalRejections}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* By Reason */}
        <div className="bg-white p-4 rounded-lg shadow">
          <h3 className="text-lg font-semibold mb-4">Por Motivo:</h3>
          <div className="space-y-2">
            {analytics.byReason.map(({ reason, count, percentage }) => (
              <div key={reason} className="flex justify-between items-center">
                <span className="text-sm">{reason}:</span>
                <div className="flex items-center gap-2">
                  <div className="w-32 bg-gray-200 rounded-full h-2">
                    <div 
                      className="bg-blue-600 h-2 rounded-full" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <span className="text-sm font-medium">{count} ({percentage.toFixed(0)}%)</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* By Stage */}
        <div className="bg-white p-4 rounded-lg shadow">
          <h3 className="text-lg font-semibold mb-4">Por Etapa:</h3>
          <div className="space-y-2">
            {analytics.byStage.map(({ stage, count, percentage }) => (
              <div key={stage} className="flex justify-between items-center">
                <span className="text-sm">{stage}:</span>
                <div className="flex items-center gap-2">
                  <div className="w-32 bg-gray-200 rounded-full h-2">
                    <div 
                      className="bg-red-600 h-2 rounded-full" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <span className="text-sm font-medium">{count} ({percentage.toFixed(0)}%)</span>
                </div>
              </div>
