1. Implementar rate limiting por usuário:
```typescript
const EMAIL_LIMITS = {
  DAILY_LIMIT: 200, // emails por dia por usuário
  HOURLY_LIMIT: 50,  // emails por hora por usuário
  BULK_LIMIT: 100,   // máximo de destinatários por envio em lote
  MINUTE_LIMIT: 10   // emails por minuto (prevenir spam)
}

class RateLimiter {
  async checkLimit(userId: string, type: 'daily' | 'hourly' | 'minute'): Promise<boolean> {
    const count = await this.getEmailCount(userId, type)
    return count < EMAIL_LIMITS[`${type.toUpperCase()}_LIMIT`]
  }
}
```

