```typescript
export async function emailPermissionMiddleware(req: Request, res: Response, next: NextFunction) {
  const user = await getCurrentUser(req)

  if (!user.permissions.includes('send_emails')) {
    return res.status(403).json({ error: 'Sem permissão para enviar emails' })
  }

  const canSend = await rateLimiter.checkLimit(user.id, 'minute')
  if (!canSend) {
    return res.status(429).json({ error: 'Limite de envio excedido' })
  }

  next()
}
