          <VirtualizedTable candidates={candidates} />
        ) : (
          <CandidateTable candidates={candidates} />
        )
      )}
    </div>
  )
}

// React Query para cache
const useCandidates = (vagaId: string, filters: CandidateFilters) => {
  return useQuery({
    queryKey: ['candidates', vagaId, filters],
    queryFn: () => fetchCandidates(vagaId, filters),
    staleTime: 5 * 60 * 1000, // 5 minutos
    cacheTime: 10 * 60 * 1000, // 10 minutos
    refetchOnWindowFocus: false
  })
}
