Pseudo-código:
```typescript
const useRealtimeUpdates = (vagaId: string) => {
  const queryClient = useQueryClient()

  useEffect(() => {
    const subscription = supabase
      .channel(`vaga_${vagaId}_candidates`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'candidatos',
        filter: `vaga_aplicada_id=eq.${vagaId}`
      }, (payload) => {
        // Atualizar cache local
        if (payload.eventType === 'UPDATE') {
          queryClient.setQueryData(
            ['candidates', vagaId],
            (oldData: Candidato[]) => 
              oldData?.map(c => 
                c.id === payload.new.id ? { ...c, ...payload.new } : c
              )
          )

          // Mostrar notificação se alteração foi feita por outro usuário
          if (payload.new.alterado_por !== currentUser.id) {
            toast.info(
              `${payload.new.nome_completo} foi movido para ${payload.new.etapa_atual}`,
              { duration: 3000 }
            )
          }
        }

        if (payload.eventType === 'INSERT') {
          queryClient.invalidateQueries(['candidates', vagaId])
          toast.success('Novo candidato aplicou para esta vaga!')
        }
      })
      .subscribe()

    return () => {
      subscription.unsubscribe()
    }
  }, [vagaId, queryClient])
}

// Integração com sistema de emails
const EmailIntegration = () => {
  const sendBulkEmail = async (candidateIds: string[], templateId: string) => {
    try {
      const response = await fetch('/api/emails/bulk-send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          candidateIds,
          templateId,
          vagaId
        })
      })

      if (response.ok) {
        toast.success(`Email enviado para ${candidateIds.length} candidatos`)

        // Registrar no histórico
        await Promise.all(candidateIds.map(candidateId => 
          supabase.from('candidatos_historico').insert({
            candidato_id: candidateId,
            vaga_id: vagaId,
            tipo_evento: 'email_enviado',
            descricao: `Email enviado usando template ${templateId}`,
            alterado_por: currentUser.id
          })
        ))
      }
    } catch (error) {
      toast.error('Erro ao enviar emails')
    }
  }

  return { sendBulkEmail }
}

