const RecentChangeIndicator = ({ candidate }: { candidate: Candidato }) => {
  const isRecent = isAfter(
    candidate.atualizado_em,
    subMinutes(new Date(), 5)
  )

  if (!isRecent) return null

  return (
    <span className="recent-change-indicator" title="Alterado recentemente">
      🔄
    </span>
  )
}
